## CHECK 9: NO COORDINATE OVERLAP BETWEEN WORKERS

RULE: Worker1 and Worker2 must have non-overlapping coordinate ranges (within same stage)

DETECTION:
```javascript
function hasOverlap(w1_min, w1_max, w2_min, w2_max) {
  const w1_max_in_w2 = (w1_max >= w2_min) && (w1_max <= w2_max);
  const w1_min_in_w2 = (w1_min >= w2_min) && (w1_min <= w2_max);
  const w2_max_in_w1 = (w2_max >= w1_min) && (w2_max <= w1_max);
  const w2_min_in_w1 = (w2_min >= w1_min) && (w2_min <= w1_max);

  return w1_max_in_w2 || w1_min_in_w2 || w2_max_in_w1 || w2_min_in_w1;
}

for (let stage of Object.values(plan.stages)) {
  const w1 = stage.Worker1;
  const w2 = stage.Worker2;

  if (w1 && w2 && w1.coordinates && w2.coordinates) {
    // Check X axis
    if (hasOverlap(w1.coordinates.xMin, w1.coordinates.xMax, 
                   w2.coordinates.xMin, w2.coordinates.xMax)) {
      FAIL: `Stage ${w1.stageNumber} X-axis overlap: W1=[${w1.coordinates.xMin},${w1.coordinates.xMax}], W2=[${w2.coordinates.xMin},${w2.coordinates.xMax}]`
    }

    // Check Z axis
    if (hasOverlap(w1.coordinates.zMin, w1.coordinates.zMax,
                   w2.coordinates.zMin, w2.coordinates.zMax)) {
      FAIL: `Stage ${w1.stageNumber} Z-axis overlap: W1=[${w1.coordinates.zMin},${w1.coordinates.zMax}], W2=[${w2.coordinates.zMin},${w2.coordinates.zMax}]`
    }
  }
}
```

PASS CONDITION: For each stage/axis, hasOverlap() returns false

ERROR MESSAGE FORMAT:
```
✗ CHECK 9 FAILED: Coordinate Overlap Between Workers
  Stage [N] [AXIS]-axis overlap:
  Worker1 [AXIS]: [MIN1]-[MAX1]
  Worker2 [AXIS]: [MIN2]-[MAX2]
  Both workers can place blocks at [OVERLAP_RANGE] (invalid!)
  Fix: Separate ranges with buffer.
  Example: Worker1 [MIN1]-[MID], Worker2 [MID+1]-[MAX2]
```

