## CHECK 15: CONSTRAINTS MATCH COORDINATE BOUNDARIES

RULE: Constraints must reference the SAME coordinate values as the task coordinates

DETECTION:
```javascript
// Extract numbers from coordinates
function extractCoordValue(obj, axis) { // axis = 'xMin', 'xMax', etc.
  return obj.coordinates?.[axis];
}

for (let stage of Object.values(plan.stages)) {
  for (let worker of Object.values(stage)) {
    if (!worker.coordinates || !worker.constraints) continue;

    const xMin = worker.coordinates.xMin;
    const xMax = worker.coordinates.xMax;
    const zMin = worker.coordinates.zMin;
    const zMax = worker.coordinates.zMax;
    const yMin = worker.coordinates.yMin;
    const yMax = worker.coordinates.yMax;

    // Check constraints for coordinate references
    for (let constraint of worker.constraints) {
      const constraintText = constraint.toLowerCase();

      // Extract numbers from constraint (regex: x:?(\d+))
      const xMatches = constraintText.match(/x:?\s*(\-?\d+)/g);
      const yMatches = constraintText.match(/y:?\s*(\-?\d+)/g);
      const zMatches = constraintText.match(/z:?\s*(\-?\d+)/g);

      // Verify extracted values match actual coordinates
      if (xMatches) {
        for (let match of xMatches) {
          const val = parseInt(match.match(/\-?\d+/)[0]);
          if (val !== xMin && val !== xMax && (val < xMin || val > xMax)) {
            FAIL: `${worker.worker} stage ${worker.stageNumber} constraint mismatch: constraint says x:${val}, coordinate range is [${xMin},${xMax}]`
          }
        }
      }

      // Same for Y and Z
      if (yMatches) {
        for (let match of yMatches) {
          const val = parseInt(match.match(/\-?\d+/)[0]);
          if (val !== yMin && val !== yMax && (val < yMin || val > yMax)) {
            FAIL: `${worker.worker} stage ${worker.stageNumber} constraint mismatch: constraint says y:${val}, coordinate range is [${yMin},${yMax}]`
          }
        }
      }
    }
  }
}
```

